// Badge lives in the header; ctx.api.ui.inject tracks it so it is
// removed automatically when this plugin is suspended or deleted.
var badge = document.createElement('span');
badge.className = 'plugin-save-indicator';
badge.textContent = 'Saved';
badge.setAttribute('aria-live', 'polite');
ctx.api.ui.inject('.header', badge, 'append');

// Middleware registrations are also tracked and auto-removed.
ctx.api.middleware.register({
  name: 'save-indicator',
  operations: ['card.save'],
  handler: async function(mw, next) {
    await next();
    badge.classList.add('visible');
    if (ctx._saveIndicatorTimer) clearTimeout(ctx._saveIndicatorTimer);
    ctx._saveIndicatorTimer = setTimeout(function() { badge.classList.remove('visible'); }, 1500);
  }
});

ctx.logger.info('Auto-save indicator ready');

teardownJs:
// Tracked resources (badge, middleware) are cleaned up automatically;
// only the pending timer needs manual cleanup.
if (ctx._saveIndicatorTimer) {
  clearTimeout(ctx._saveIndicatorTimer);
  ctx._saveIndicatorTimer = null;
}
